CREATE TABLE public.vehicle_bell_demands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), post_id uuid, category text NOT NULL CHECK(category IN ('goods','returns','cars')), display_name text NOT NULL, from_place text NOT NULL, to_place text NOT NULL, vehicle_type text NOT NULL, rang_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vehicle_bell_demands TO authenticated;
GRANT ALL ON public.vehicle_bell_demands TO service_role;
ALTER TABLE public.vehicle_bell_demands ENABLE ROW LEVEL SECURITY;
CREATE POLICY paid_demand_read ON public.vehicle_bell_demands FOR SELECT TO authenticated USING(public.has_paid_bell(auth.uid()) AND public.account_allowed(auth.uid()) AND public.account_allowed(user_id));
CREATE INDEX vehicle_bell_demands_time ON public.vehicle_bell_demands(rang_at DESC);
CREATE UNIQUE INDEX vehicle_bell_demands_post_member ON public.vehicle_bell_demands(user_id,post_id) WHERE post_id IS NOT NULL;
CREATE UNIQUE INDEX vehicle_bell_demands_catalog_member ON public.vehicle_bell_demands(user_id,category,from_place,to_place,vehicle_type) WHERE post_id IS NULL;
CREATE TABLE public.vehicle_demand_chat_pairs (demand_id uuid NOT NULL REFERENCES public.vehicle_bell_demands(id), member_id uuid NOT NULL REFERENCES public.profiles(id), owner_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(demand_id,member_id));
GRANT SELECT ON public.vehicle_demand_chat_pairs TO authenticated;
GRANT ALL ON public.vehicle_demand_chat_pairs TO service_role;
ALTER TABLE public.vehicle_demand_chat_pairs ENABLE ROW LEVEL SECURITY;
CREATE POLICY demand_pair_participants ON public.vehicle_demand_chat_pairs FOR SELECT TO authenticated USING(auth.uid() IN(member_id,owner_id));
CREATE OR REPLACE FUNCTION public.ring_vehicle_demand(_post uuid DEFAULT NULL,_category text DEFAULT NULL,_from text DEFAULT NULL,_to text DEFAULT NULL,_vehicle text DEFAULT NULL,_name_consent boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); p public.posts; target uuid; cname text; cat text; f text; t text; v text; BEGIN
IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF;
IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF;
IF NOT coalesce(_name_consent,false) THEN RAISE EXCEPTION 'NAME_CONSENT_REQUIRED'; END IF;
SELECT trim(full_name) INTO cname FROM public.profiles WHERE id=caller; IF coalesce(cname,'')='' THEN RAISE EXCEPTION 'PROFILE_NAME_REQUIRED'; END IF;
IF _post IS NOT NULL THEN SELECT * INTO p FROM public.posts WHERE id=_post AND module='vehicle'; IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; target:=public.ring_post(_post); f:=coalesce(p.from_place,'');t:=coalesce(p.to_place,'');v:=coalesce(p.vehicle_type,'');cat:=CASE WHEN lower(v) IN ('car','innova','swift dzire','ertiga','bolero','suv','sedan','hatchback','taxi') THEN 'cars' WHEN lower(trim(f))=lower(trim(t)) THEN 'goods' ELSE 'returns' END;
ELSE cat:=_category;f:=trim(coalesce(_from,''));t:=trim(coalesce(_to,''));v:=trim(coalesce(_vehicle,'')); END IF;
IF cat IS NULL OR cat NOT IN ('goods','returns','cars') OR f='' OR t='' OR v='' OR length(f)>80 OR length(t)>80 OR length(v)>100 THEN RAISE EXCEPTION 'VEHICLE_ROUTE_REQUIRED'; END IF;
INSERT INTO public.vehicle_bell_demands(user_id,post_id,category,display_name,from_place,to_place,vehicle_type) VALUES(caller,_post,cat,cname,f,t,v) ON CONFLICT DO NOTHING; RETURN target; END $$;
REVOKE ALL ON FUNCTION public.ring_vehicle_demand(uuid,text,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ring_vehicle_demand(uuid,text,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.list_vehicle_bell_demands() RETURNS SETOF public.vehicle_bell_demands LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN QUERY SELECT d.* FROM public.vehicle_bell_demands d WHERE public.account_allowed(d.user_id) ORDER BY d.rang_at DESC; END $$;
REVOKE ALL ON FUNCTION public.list_vehicle_bell_demands() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_vehicle_bell_demands() TO authenticated;
CREATE OR REPLACE FUNCTION public.open_vehicle_demand_chat(_demand uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.vehicle_bell_demands; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) OR NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO d FROM public.vehicle_bell_demands WHERE id=_demand; IF d.id IS NULL OR d.user_id=caller OR NOT public.account_allowed(d.user_id) THEN RAISE EXCEPTION 'DEMAND_UNAVAILABLE'; END IF; INSERT INTO public.vehicle_demand_chat_pairs(demand_id,member_id,owner_id) VALUES(d.id,caller,d.user_id) ON CONFLICT DO NOTHING; RETURN d.user_id; END $$;
REVOKE ALL ON FUNCTION public.open_vehicle_demand_chat(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.open_vehicle_demand_chat(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL THEN EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;